import { NextResponse } from 'next/server';
import { apiGetOrNull } from '../../../lib/api';

/**
 * The sample device export, as a file (HR-02 build spec §5.2).
 *
 * Generated by the API from the seeded company every time it is asked for, so
 * the names and numbers in it are the ones on the screens beside it.
 */
export async function GET(): Promise<NextResponse> {
  const sample = await apiGetOrNull<{ filename: string; content: string }>(
    '/attendance/sample/file',
  );

  if (sample === null) {
    return new NextResponse('', { status: 403 });
  }

  return new NextResponse(`${BOM}${sample.content}`, {
    headers: {
      'content-type': 'text/csv; charset=utf-8',
      'content-disposition': `attachment; filename="${sample.filename}"`,
      'cache-control': 'no-store',
    },
  });
}

/**
 * The byte-order mark Excel wants: this file is opened in Excel before it is
 * sent to a provider. Written as an escape, which a literal mark is not.
 */
const BOM = '﻿';
